/* 只合并相邻且相同的大写字母，不做全串频数统计。 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int main(void)  {
    char text[10001];
    scanf("%10000s", text);
    int length = (int)strlen(text);
    int start = 0;
    /* start 是段首，end 扩展到第一个不同字符或串尾，区间为 [start,end)。 */
    while (start < length)  {
        int end = start + 1;
        while (end < length && text[end] == text[start])  {
            ++end;
        }
        /* 输出段首字母和 end-start，然后从 end 开始下一段，最后一段也正常输出。 */
        printf("%c %d\n", text[start], end - start);
        start = end;
    }
    return 0;
}

