/* 只合并相邻且相同的大写字母，不做全串频数统计。 */
import java.io.*;
import java.util.*;
public class Main  {
    static final class FastScanner  {
        private final InputStream input = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int position = 0;
        private int length = 0;
        private int read() throws IOException  {
            if (position == length)  {
                length = input.read(buffer);
                position = 0;
                if (length < 0)  {
                    return -1;
                }
            }
            return buffer[position++];
        }
        String next() throws IOException  {
            int value;
            do  {
                value = read();
            }
            while (value <= 32 && value != -1);
            StringBuilder token = new StringBuilder();
            while (value > 32 && value != -1)  {
                token.append((char) value);
                value = read();
            }
            return token.toString();
        }
        int nextInt() throws IOException  {
            return Integer.parseInt(next());
        }
        long nextLong() throws IOException  {
            return Long.parseLong(next());
        }
    }
    public static void main(String[] args) throws Exception  {
        FastScanner scanner = new FastScanner();
        String text = scanner.next();
        StringBuilder answer = new StringBuilder();
        int start = 0;
        /* start 是段首，end 扩展到第一个不同字符或串尾，区间为 [start,end)。 */
        while (start < text.length())  {
            int end = start + 1;
            while (end < text.length() && text.charAt(end) == text.charAt(start))  {
                end++;
            }
            answer.append(text.charAt(start)).append(' ').append(end - start).append('\n');
            start = end;
        }
        System.out.print(answer);
    }
    /* 输出段首字母和 end-start，然后从 end 开始下一段，最后一段也正常输出。 */
}

