;
fn main()  {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let text = input.trim().as_bytes();
    let mut answer = String::new();
    let mut start = 0usize;
    /* start 是段首，end 扩展到第一个不同字符或串尾，区间为 [start,end)。 */
    while start < text.len()  {
        let mut end = start + 1;
        while end < text.len() && text[end] == text[start]  {
            end += 1;
        }
        answer.push_str(&format!("{} {}\n", text[start] as char, end - start));
        start = end;
    }
    print!("{}", answer);
    /* 输出段首字母和 end-start，然后从 end 开始下一段，最后一段也正常输出。 */
}
